import{_ as h,o as t,c as i,a3 as a}from"./chunks/framework.DX_KL3e0.js";const b=JSON.parse('{"title":"Thông Báo - Truyền Thông","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/thong-bao-truyen-thong.md","filePath":"chuc-nang/thong-bao-truyen-thong.md","lastUpdated":1782639524000}'),o={name:"chuc-nang/thong-bao-truyen-thong.md"};function c(g,n,l,r,e,u){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="thong-bao-truyen-thong" tabindex="-1">Thông Báo - Truyền Thông <a class="header-anchor" href="#thong-bao-truyen-thong" aria-label="Permalink to &quot;Thông Báo - Truyền Thông&quot;">​</a></h1><p>Phân hệ <strong>Thông Báo - Truyền Thông</strong> là bảng tin nội bộ dùng để phát hành thông báo chung trong tổ chức. Người có quyền có thể đăng bài, ghim bài, chỉnh sửa, xóa và gửi thông báo ra các kênh nhận tin đã cấu hình.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/tra-cuu/thong-bao</code>.</li><li><strong>Ai dùng được:</strong> tất cả người dùng có quyền xem thông báo; quyền đăng/xóa phụ thuộc phân quyền module.</li><li><strong>Dùng để:</strong> đọc thông báo nội bộ, tương tác bằng reaction, mở ảnh/tệp đính kèm, theo dõi bài ghim.</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p>Trang hiển thị theo dạng <strong>bảng tin</strong>:</p><ul><li>Phần trên cùng là ô soạn bài nếu tài khoản của bạn có quyền đăng.</li><li>Bên dưới là danh sách bài viết đã phát hành.</li><li>Bài được <strong>ghim</strong> luôn nổi bật và nằm trên.</li><li>Mỗi bài có thể có ảnh, tệp đính kèm và reaction.</li></ul><h2 id="cac-thao-tac-chinh" tabindex="-1">Các thao tác chính <a class="header-anchor" href="#cac-thao-tac-chinh" aria-label="Permalink to &quot;Các thao tác chính&quot;">​</a></h2><h3 id="đoc-thong-bao" tabindex="-1">Đọc thông báo <a class="header-anchor" href="#đoc-thong-bao" aria-label="Permalink to &quot;Đọc thông báo&quot;">​</a></h3><ol><li>Mở <code>/tra-cuu/thong-bao</code>.</li><li>Xem bài ghim trước, sau đó cuộn xuống các bài mới hơn.</li><li>Bấm vào vùng đính kèm để mở ảnh hoặc tải tệp.</li></ol><h3 id="đang-thong-bao-moi" tabindex="-1">Đăng thông báo mới <a class="header-anchor" href="#đang-thong-bao-moi" aria-label="Permalink to &quot;Đăng thông báo mới&quot;">​</a></h3><ol><li>Nhấn ô <strong>Đăng thông báo...</strong>.</li><li>Nhập nội dung cần phát hành.</li><li>Đính kèm ảnh hoặc tệp nếu cần.</li><li>Nhấn <strong>Đăng bài</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Nội dung ngắn, rõ và có mốc thời gian cụ thể sẽ giúp người đọc nắm thông tin nhanh hơn.</p></div><h3 id="tha-reaction" tabindex="-1">Thả reaction <a class="header-anchor" href="#tha-reaction" aria-label="Permalink to &quot;Thả reaction&quot;">​</a></h3><ol><li>Mở một bài thông báo.</li><li>Nhấn nút <strong>Thích</strong>.</li><li>Chọn biểu tượng cảm xúc phù hợp.</li></ol><p>Reaction giúp đội phát hành biết mức độ quan tâm mà không cần thêm bình luận.</p><h3 id="ghim-bai" tabindex="-1">Ghim bài <a class="header-anchor" href="#ghim-bai" aria-label="Permalink to &quot;Ghim bài&quot;">​</a></h3><p>Người có quyền đăng bài có thể mở menu của bài viết rồi chọn <strong>Ghim bài</strong> hoặc <strong>Bỏ ghim</strong>.</p><h3 id="chinh-sua-hoac-xoa-bai" tabindex="-1">Chỉnh sửa hoặc xóa bài <a class="header-anchor" href="#chinh-sua-hoac-xoa-bai" aria-label="Permalink to &quot;Chỉnh sửa hoặc xóa bài&quot;">​</a></h3><ol><li>Mở menu của bài viết.</li><li>Chọn <strong>Sửa bài</strong> để cập nhật nội dung.</li><li>Chọn <strong>Xóa bài</strong> nếu bài không còn hiệu lực.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Chỉ nên xóa khi đăng nhầm hoặc sai hoàn toàn. Với thông báo đã phát hành rộng, nên sửa và bổ sung nội dung thay vì xóa nếu muốn giữ lịch sử truyền thông.</p></div><h2 id="tep-đinh-kem-va-anh" tabindex="-1">Tệp đính kèm và ảnh <a class="header-anchor" href="#tep-đinh-kem-va-anh" aria-label="Permalink to &quot;Tệp đính kèm và ảnh&quot;">​</a></h2><ul><li>Ảnh có thể xem trực tiếp trong bài.</li><li>Tệp đính kèm mở qua liên kết tải xuống.</li><li>Một bài có thể có cả ảnh lẫn tệp tài liệu.</li></ul><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Vì sao tôi không thấy ô đăng bài?</strong><br> Tài khoản của bạn chưa có quyền tạo thông báo. Hãy liên hệ Admin nếu cần được cấp quyền.</p><p><strong>Vì sao bài viết của tôi không nằm trên cùng?</strong><br> Chỉ bài được ghim mới luôn nằm trên. Các bài còn lại sắp theo thời gian phát hành.</p><p><strong>Tôi có thể dùng phân hệ này như mạng xã hội nội bộ không?</strong><br> Nên dùng theo mục đích truyền thông công việc, thông báo chính sách, nhắc việc chung hoặc cập nhật nội bộ.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tra-cuu.html">Tra cứu</a> · <a href="/help/chuc-nang/van-ban-quyet-dinh.html">Văn Bản - Quyết Định</a></p>',28)])])}const m=h(o,[["render",c]]);export{b as __pageData,m as default};
